package com.procurement.rfq.service;import com.procurement.common.exception.ResourceNotFoundException;import com.procurement.common.response.*;import com.procurement.rfq.dto.response.*;import com.procurement.rfq.mapper.*;import com.procurement.rfq.repository.*;import com.procurement.rfq.specification.*;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class RfqLineServiceImpl implements RfqLineService{private final RfqLineRepository repo;private final RfqMapper mapper;public RfqLineServiceImpl(RfqLineRepository r,RfqMapper m){repo=r;mapper=m;}@Transactional(readOnly=true)public PageResponse<RfqLineResponse>search(Long r,Long p,Pageable page){Page<RfqLineResponse>x=repo.findAll(RfqLineSpecification.search(r,p),page).map(mapper::toLineResponse);return new PageResponse<>(x.getContent(),x.getNumber(),x.getSize(),x.getTotalElements(),x.getTotalPages(),x.isLast());}@Transactional(readOnly=true)public RfqLineResponse get(Long id){return repo.findById(id).map(mapper::toLineResponse).orElseThrow(()->new ResourceNotFoundException("RFQ line not found: "+id));}}
